}", "newString": "function frontendTemplate(node, document, options) {
    const figure = document.createElement('figure');
    figure.setAttribute('class', 'kg-card kg-transistor-card');

    // The {uuid} placeholder is substituted with the member UUID at request time.
    // When a siteUuid is available it's passed through as the `ctx` query param
    // so the embed can be attributed to the correct site.
    let embedUrl = 'https://partner.transistor.fm/ghost/embed/{uuid}';
    if (options.siteUuid) {
        embedUrl += `?ctx=${options.siteUuid}`;
    }

    // The embed is lazy-loaded: `data-src` is promoted to `src` by the inline
    // script below once the parent background colour has been detected.
    const iframe = document.createElement('iframe');
    iframe.setAttribute('data-kg-transistor-embed', '');
    iframe.setAttribute('data-src', embedUrl);
    iframe.setAttribute('width', '100%');
    iframe.setAttribute('frameborder', '0');
    iframe.setAttribute('scrolling', 'no');
    iframe.setAttribute('title', 'Transistor podcast embed');

    // Fallback for browsers with JavaScript disabled - loads the embed directly.
    const noscript = document.createElement('noscript');
    const fallbackIframe = document.createElement('iframe');
    fallbackIframe.setAttribute('src', embedUrl);
    fallbackIframe.setAttribute('width', '100%');
    fallbackIframe.setAttribute('frameborder', '0');
    fallbackIframe.setAttribute('scrolling', 'no');
    fallbackIframe.setAttribute('title', 'Transistor podcast embed');
    noscript.appendChild(fallbackIframe);

    const script = document.createElement('script');
    script.textContent = transistorEmbedScript();

    figure.appendChild(iframe);
    figure.appendChild(noscript);
    figure.appendChild(script);

    return renderWithVisibility({element: figure, type: 'inner'}, node.visibility, options);
}

// Inline script that detects the background colour of the embed's surroundings
// and promotes the iframe's `data-src` to `src`, appending the detected colour
// so the Transistor player can match the site theme.
function transistorEmbedScript() {
    return `(function () {
    function setSrcBackgroundFromParent(iframe) {
        if (!iframe) {
            return;
        }
        var src = iframe.getAttribute('data-src');
        if (!src) {
            return;
        }
        var background = '';
        try {
            var el = iframe.parentNode;
            while (el && el.nodeType === 1) {
                var color = window.getComputedStyle(el).backgroundColor;
                if (color && color !== 'transparent' && color !== 'rgba(0, 0, 0, 0)') {
                    background = color;
                    break;
                }
                el = el.parentNode;
            }
        } catch (e) {
            background = '';
        }
        if (background) {
            src += (src.indexOf('?') === -1 ? '?' : '&') + 'background=' + encodeURIComponent(background);
        }
        iframe.setAttribute('src', src);
    }

    var iframes = document.querySelectorAll('iframe[data-kg-transistor-embed]');
    for (var i = 0; i < iframes.length; i++) {
        setSrcBackgroundFromParent(iframes[i]);
    }
})();`;
